import * as XLSX from 'xlsx';
import type { PlanVoucherImportRowDto } from '../../../services/fpc/types';

/** Normalize Excel header → canonical field key. */
function mapHeader(raw: string): string | null {
  const h = (raw || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, '')
    .replace(/[_-]/g, '');

  const aliases: Record<string, string> = {
    madonvi: 'companyCode',
    companycode: 'companyCode',
    branchcode: 'companyCode',
    companyid: 'companyCode',
    madvcs: 'companyCode',
    donvicoso: 'companyCode',
    chinhanh: 'companyCode',
    machiphi: 'costCode',
    costcode: 'costCode',
    chiphi: 'costCode',
    nam: 'year',
    year: 'year',
    planyear: 'year',
    thang: 'month',
    month: 'month',
    planmonth: 'month',
    sotienkehoach: 'plannedAmount',
    kehoach: 'plannedAmount',
    plannedamount: 'plannedAmount',
    amount: 'plannedAmount',
    phaichi: 'mustPay',
    mustpay: 'mustPay',
    diengiai: 'note',
    note: 'note',
    ghichu: 'note',
    description: 'note',
  };
  return aliases[h] ?? null;
}

function cellStr(v: unknown): string {
  if (v == null) return '';
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return String(v).trim();
}

function cellNum(v: unknown): number {
  if (v == null || v === '') return 0;
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  const s = String(v).replace(/\s/g, '').replace(/,/g, '');
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function cellInt(v: unknown): number {
  return Math.trunc(cellNum(v));
}

/**
 * Parse sheet `KeHoach` (or first sheet) → import rows.
 * Expects header row with MaDonVi, MaChiPhi, Nam, Thang, …
 */
export function parsePlanVoucherImportFile(file: ArrayBuffer): PlanVoucherImportRowDto[] {
  const wb = XLSX.read(file, { type: 'array' });
  const sheetName =
    wb.SheetNames.find(n => n.localeCompare('KeHoach', undefined, { sensitivity: 'accent' }) === 0)
    ?? wb.SheetNames.find(n => /ke\s*hoach|import|data/i.test(n))
    ?? wb.SheetNames[0];
  if (!sheetName) return [];

  const sheet = wb.Sheets[sheetName];
  const matrix = XLSX.utils.sheet_to_json<(string | number | null | undefined)[]>(sheet, {
    header: 1,
    defval: '',
    raw: true,
  }) as unknown[][];

  if (!matrix.length) return [];

  const headerRow = matrix[0] as unknown[];
  const colMap = new Map<number, string>();
  headerRow.forEach((cell, i) => {
    const key = mapHeader(cellStr(cell));
    if (key) colMap.set(i, key);
  });

  if (colMap.size === 0) {
    throw new Error(
      'Không nhận diện được header. Cần cột: MaDonVi, MaChiPhi, Nam, Thang, SoTienKeHoach (tải file mẫu).',
    );
  }

  const rows: PlanVoucherImportRowDto[] = [];
  for (let r = 1; r < matrix.length; r++) {
    const line = matrix[r] as unknown[];
    if (!line || line.every(c => cellStr(c) === '')) continue;

    const obj: Record<string, unknown> = {};
    colMap.forEach((key, i) => {
      obj[key] = line[i];
    });

    const companyCode = cellStr(obj.companyCode);
    const costCode = cellStr(obj.costCode);
    const year = cellInt(obj.year);
    const month = cellInt(obj.month);
    const plannedAmount = cellNum(obj.plannedAmount);
    const mustPay = cellNum(obj.mustPay);
    const note = cellStr(obj.note) || undefined;

    if (!companyCode && !costCode && plannedAmount === 0 && mustPay === 0) continue;

    rows.push({
      rowIndex: r + 1, // 1-based Excel row (header = 1)
      companyCode,
      costCode,
      year,
      month,
      plannedAmount,
      mustPay,
      note,
    });
  }

  return rows;
}
